import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapPicker from "../MapPicker";
import "./LandPredictionForm.css";

export default function LandPredictionForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    area: "",
    zoning: "",
    roadAccess: "",
    utilities: "",
    soilType: "",
    developmentPotential: "",
    cityDistance: "",
  });
  const [location, setLocation] = useState({
    lat: null,
    lng: null,
    address: "",
  });
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleFormChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleLocationChange = (loc) => {
    setLocation(loc);
  };

  const getCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation is not supported by this browser.");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        fetch(
          `https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${process.env.REACT_APP_GOOGLE_MAPS_API_KEY}`
        )
          .then((res) => res.json())
          .then((data) => {
            if (data.status === "OK") {
              const firstResult = data.results[0];
              setLocation({
                lat,
                lng,
                address: firstResult.formatted_address,
              });
            } else {
              alert("Failed to get address from location.");
            }
          });
      },
      () => {
        alert("Permission denied or unable to get location.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!location.lat || !location.lng) {
      alert("Please select a location.");
      return;
    }
    const payload = {
      location: location.address,
      area: form.area,
      zoning: form.zoning,
      roadAccess: form.roadAccess,
      utilities: form.utilities,
      soilType: form.soilType,
      developmentPotential: form.developmentPotential,
      cityDistance: form.cityDistance,
      latitude: location.lat,
      longitude: location.lng,
    };

    setLoading(true);
    setResult(null);
    try {
      const response = await fetch(
        `${process.env.REACT_APP_BACKEND_URL}/predict/land`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }
      );
      const data = await response.json();
      setResult(data.price);
    } catch (error) {
      console.error(error);
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  return (
    <div className="land-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="land-predict-panels">
        <div className="land-details-card">
          <h2>Land Details</h2>
          <p>Enter the details of the land to get an accurate price prediction</p>
          <button onClick={getCurrentLocation} className="location-btn">
            Use My Location
          </button>
          <MapPicker location={location} onLocationChange={handleLocationChange} />

          <form onSubmit={handleSubmit} className="details-form">
            <input
              type="text"
              name="location"
              placeholder="Selected Address"
              value={location.address}
              readOnly
              className="input-location"
            />

            <label>Area (acres)</label>
            <input
              name="area"
              type="number"
              min="0"
              step="0.1"
              placeholder="2.5"
              value={form.area}
              onChange={handleFormChange}
              required
            />

            <label>Zoning Type</label>
            <select name="zoning" value={form.zoning} onChange={handleFormChange} required>
              <option value="">Select zoning</option>
              <option>Agricultural</option>
              <option>Residential</option>
              <option>Commercial</option>
              <option>Industrial</option>
              <option>Conservation</option>
            </select>

            {/* Add other input fields similarly */}

            <button type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict Land Price"}
            </button>
          </form>
        </div>

        <div className="price-prediction-card">
          <h2>Price Prediction</h2>
          <p>Your estimated land price will appear here</p>
          {result !== null && <div className="price-result">₹ {result}</div>}
        </div>
      </div>
    </div>
  );
}
